#!/usr/bin/env bash
# Thin docker compose wrapper. One project, one command:
#
#   ./deploy/cluster.sh up        build images and start everything
#   ./deploy/cluster.sh ps        status
#   ./deploy/cluster.sh logs -f   logs
#   ./deploy/cluster.sh down      stop (keeps the postgres volume)
#   ./deploy/cluster.sh reset     stop and delete the postgres volume (demo data reloads)
#
# If deploy/secrets/compose.secrets.yml exists (generated by deploy/bootstrap.sh for a
# non-demo deployment), it is merged on top of the defaults.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"
COMPOSE=(docker compose -p datalens-rust -f deploy/docker-compose.yml)
if [ -s deploy/secrets/compose.secrets.yml ]; then
  COMPOSE+=(-f deploy/secrets/compose.secrets.yml)
fi
command="${1:-up}"
shift || true

case "$command" in
  up)
    "${COMPOSE[@]}" up -d --build "$@"
    echo
    echo "UI      : http://localhost:8091   (admin / admin — change the password)"
    echo "API     : http://localhost:8099/ping"
    echo "demo    : the 'seed' service loads the official demo data on first start"
    ;;
  down)  "${COMPOSE[@]}" down "$@" ;;
  reset) "${COMPOSE[@]}" down -v "$@" ;;
  ps|logs|restart|stop|start|build|config)
    "${COMPOSE[@]}" "$command" "$@" ;;
  *) echo "usage: $0 up|down|reset|ps|logs|restart|stop|start|build|config ..." >&2; exit 2 ;;
esac
